import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, abort
from functools import wraps
import hmac
import hashlib
import time

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')
ALLOWED_FORMATS = ['png', 'jpg', 'gif', 'webp', 'pdf']

def verify_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        sig = request.headers.get('X-Signature')
        ts = request.headers.get('X-Timestamp')
        if not sig or not ts:
            abort(401, 'Missing signature')
        if abs(time.time() - float(ts)) > 300:
            abort(401, 'Expired request')
        body = request.get_data()
        expected = hmac.new(SECRET_KEY.encode(), ts.encode() + body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            abort(401, 'Invalid signature')
        return f(*args, **kwargs)
    return decorated

def sanitize_filename(name):
    """Remove path traversal attempts"""
    return name.replace('..', '').replace('/', '').replace('\\', '')

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/convert', methods=['POST'])
@verify_signature
def convert_document():
    """Convert uploaded document to specified format using LibreOffice"""
    if 'file' not in request.files:
        abort(400, 'No file provided')

    uploaded = request.files['file']
    output_format = request.form.get('format', 'pdf')
    dpi = request.form.get('dpi', '150')
    page_range = request.form.get('pages', '')

    if output_format not in ALLOWED_FORMATS:
        abort(400, f'Unsupported format: {output_format}')

    safe_name = sanitize_filename(uploaded.filename)

    with tempfile.TemporaryDirectory() as tmpdir:
        input_path = os.path.join(tmpdir, safe_name)
        uploaded.save(input_path)

        # Build conversion command
        cmd = f'libreoffice --headless --convert-to {output_format}'

        if page_range:
            # Allow specifying page range for PDF output
            cmd += f' --outdir {tmpdir} -env:UserInstallation=file://{tmpdir}/user'
            cmd += f' --infilter="PageRange={page_range}"'
        else:
            cmd += f' --outdir {tmpdir}'

        cmd += f' {input_path}'

        # Execute conversion
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=tmpdir
        )

        if result.returncode != 0:
            return jsonify({
                'error': 'Conversion failed',
                'details': result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        # Find output file
        output_name = os.path.splitext(safe_name)[0] + '.' + output_format
        output_path = os.path.join(tmpdir, output_name)

        if not os.path.exists(output_path):
            return jsonify({'error': 'Output file not generated'}), 500

        with open(output_path, 'rb') as f:
            content = f.read()

        return content, 200, {
            'Content-Type': f'application/octet-stream',
            'Content-Disposition': f'attachment; filename="{output_name}"'
        }

@app.route('/batch', methods=['POST'])
@verify_signature
def batch_convert():
    """Queue batch conversion job"""
    job_spec = request.get_json()
    if not job_spec or 'urls' not in job_spec:
        abort(400, 'Invalid job spec')

    # Fetch and convert each URL
    results = []
    for url in job_spec['urls'][:10]:
        fetch_cmd = f"curl -sL '{url}' -o /tmp/batch_input"
        subprocess.run(fetch_cmd, shell=True, timeout=10)
        results.append({'url': url, 'status': 'queued'})

    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
